```css
/* CSS PART 2 OF 3 */

/* TRUST AND EXPERIENCE STRIP */
.trust-strip {
  position: relative;
  z-index: 2;
  background: var(--forest);
  color: var(--white);
}

.trust-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;
}

.trust-item {
  padding: 30px 24px;
  border-right: 1px solid rgba(255, 255, 255, .18);
  text-align: center;
}

.trust-item:last-child {
  border-right: 0;
}

.trust-value {
  display: block;
  margin-bottom: 5px;
  color: #f0a477;
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 2.8vw, 2.2rem);
  font-weight: 800;
  line-height: 1.1;
}

.trust-label {
  color: rgba(255, 255, 255, .85);
  font-size: .78rem;
  font-weight: 700;
}

/* INTRODUCTION AND APPROACH */
.intro-section {
  padding-block: 110px;
  background: var(--paper);
}

.intro-layout {
  display: grid;
  grid-template-columns: 1fr .85fr;
  align-items: center;
  gap: clamp(50px, 8vw, 110px);
}

.intro-copy h2 {
  max-width: 620px;
}

.intro-copy p {
  max-width: 610px;
  color: var(--ink-soft);
}

.intro-image-wrap {
  position: relative;
  min-height: 480px;
}

.intro-image {
  width: 100%;
  height: 480px;
  border-radius: var(--radius-large);
  object-fit: cover;
  object-position: center;
}

.intro-image-wrap::after {
  position: absolute;
  right: -14px;
  bottom: -14px;
  z-index: -1;
  width: 65%;
  height: 65%;
  border: 2px solid var(--orange);
  border-radius: var(--radius-large);
  content: "";
}

.intro-highlight {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-top: 30px;
  padding: 22px;
  border-left: 3px solid var(--orange);
  background: var(--surface);
}

.intro-highlight p {
  margin: 0;
  color: var(--ink);
  font-size: .92rem;
  font-weight: 600;
}

/* SERVICES */
.services-section {
  padding-block: 105px;
  background: var(--surface);
}

.section-heading {
  max-width: 720px;
  margin-bottom: 55px;
}

.section-heading p {
  max-width: 590px;
  color: var(--ink-soft);
}

.services-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: 75px;
  align-items: start;
}

.services-intro {
  position: sticky;
  top: 35px;
}

.services-intro h2 {
  margin-bottom: 22px;
}

.services-intro p {
  color: var(--ink-soft);
}

.services-list {
  border-top: 1px solid #c9cbc3;
}

.service-item {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 22px;
  padding: 29px 0;
  border-bottom: 1px solid #c9cbc3;
}

.service-number {
  color: var(--orange-dark);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 800;
}

.service-item h3 {
  margin-bottom: 8px;
}

.service-item p {
  max-width: 530px;
  margin-bottom: 0;
  color: var(--ink-soft);
  font-size: .92rem;
}

/* PROJECT GALLERY */
.projects-section {
  padding-block: 110px;
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 45px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-gallery {
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  grid-template-rows: 260px 260px;
  gap: 20px;
}

.project-item {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border-radius: var(--radius-large);
  background: var(--forest-dark);
  isolation: isolate;
}

.project-item:first-child {
  grid-row: span 2;
}

.project-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 450ms ease;
}

.project-item:hover img {
  transform: scale(1.045);
}

.project-item::after {
  position: absolute;
  z-index: 0;
  inset: 30% 0 0;
  background: linear-gradient(
    0deg,
    rgba(20, 31, 29, .9),
    transparent
  );
  content: "";
}

.project-caption {
  position: absolute;
  z-index: 1;
  right: 25px;
  bottom: 23px;
  left: 25px;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 6px;
  color: #f0a477;
  font-size: .69rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.project-caption h3 {
  margin: 0;
  color: var(--white);
  font-size: 1.25rem;
}

/* ROOF ATTENTION / HAIL RESTORATION */
.roof-section {
  padding-block: 105px;
  background: var(--forest-dark);
  color: var(--white);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 85px;
}

.roof-copy .eyebrow {
  color: #f0a477;
}

.roof-copy h2 {
  color: var(--white);
}

.roof-copy p {
  color: rgba(255, 255, 255, .8);
}

.roof-image {
  width: 100%;
  height: 480px;
  border-radius: var(--radius-large);
  object-fit: cover;
}

.roof-checklist {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 22px;
  margin: 28px 0 35px;
  padding: 0;
  list-style: none;
}

.roof-checklist li {
  position: relative;
  padding-left: 23px;
  color: rgba(255, 255, 255, .9);
  font-size: .9rem;
}

.roof-checklist li::before {
  position: absolute;
  top: .65em;
  left: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #f0a477;
  content: "";
}

/* ROOFING PROCESS */
.process-section {
  padding-block: 105px;
  background: var(--white);
}

.process-heading {
  max-width: 740px;
  margin-bottom: 60px;
}

.process-heading p {
  color: var(--ink-soft);
}

.process-steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
}

.process-step {
  position: relative;
  padding: 32px 25px 15px 0;
}

.process-step:not(:last-child)::after {
  position: absolute;
  top: -5px;
  right: 22px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--orange);
  content: "";
}

.process-step-number {
  display: block;
  margin-bottom: 22px;
  color: var(--orange-dark);
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
}

.process-step h3 {
  margin-bottom: 12px;
}

.process-step p {
  max-width: 245px;
  margin: 0;
  color: var(--ink-soft);
  font-size: .88rem;
  line-height: 1.75;
}

/* ESTIMATE CALCULATOR PROMOTION */
.estimate-banner {
  position: relative;
  overflow: hidden;
  padding-block: 75px;
  background: var(--orange);
  color: var(--white);
}

.estimate-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 45px;
}

.estimate-copy {
  max-width: 680px;
}

.estimate-copy h2 {
  margin-bottom: 12px;
  color: var(--white);
}

.estimate-copy p {
  margin: 0;
  color: rgba(255, 255, 255, .9);
}

.estimate-banner .btn {
  flex-shrink: 0;
  background: var(--white);
  color: var(--ink);
}

.estimate-banner .btn:hover {
  background: var(--forest-dark);
  color: var(--white);
}
```

