/* CSS PART 3 OF 3 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: 110px;
  background: var(--surface);
}

.contact-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  align-items: start;
  gap: 85px;
}

.contact-copy h2 {
  margin-bottom: 22px;
}

.contact-copy > p {
  color: var(--ink-soft);
}

.contact-details {
  display: grid;
  gap: 18px;
  margin-top: 35px;
}

.contact-detail {
  display: flex;
  align-items: center;
  gap: 15px;
  color: var(--ink);
  font-weight: 700;
}

.contact-detail a {
  transition: color var(--transition);
}

.contact-detail a:hover {
  color: var(--orange-dark);
}

.contact-form {
  padding: clamp(25px, 4vw, 45px);
  border: 1px solid var(--line);
  border-radius: var(--radius-large);
  background: var(--white);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 28px;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-field.full-width {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: .8rem;
  font-weight: 800;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid #cdd0c9;
  border-radius: var(--radius);
  background: #fcfcfa;
  color: var(--ink);
  transition: border-color var(--transition);
}

.form-field textarea {
  min-height: 140px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858d88;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--forest);
  outline: 2px solid rgba(52, 77, 71, .18);
  outline-offset: 1px;
}

.form-submit {
  width: 100%;
  margin-top: 24px;
}

.form-note {
  margin: 15px 0 0;
  color: var(--muted);
  font-size: .75rem;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding-block: 55px 30px;
  background: var(--forest-dark);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 45px;
}

.footer-brand {
  max-width: 390px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand p {
  margin-top: 18px;
  color: rgba(255, 255, 255, .7);
  font-size: .88rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 22px 32px;
}

.footer-links a {
  color: rgba(255, 255, 255, .85);
  font-size: .83rem;
  font-weight: 700;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: #f0a477;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 25px;
  border-top: 1px solid rgba(255, 255, 255, .18);
  color: rgba(255, 255, 255, .62);
  font-size: .75rem;
}

/* ACCESSIBLE KEYBOARD FOCUS */
:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

.contact-form :focus-visible {
  outline-color: var(--forest);
}

/* TABLET */
@media (max-width: 1000px) {
  :root {
    --gutter: 32px;
  }

  .header-inner {
    gap: 18px;
  }

  .brand img {
    max-width: 145px;
  }

  .main-nav {
    gap: 15px;
  }

  .main-nav a:not(.btn) {
    font-size: .76rem;
  }

  .header-contact .btn {
    padding-inline: 15px;
  }

  .intro-layout,
  .roof-layout {
    gap: 45px;
  }

  .services-layout {
    gap: 40px;
  }

  .contact-layout {
    gap: 45px;
  }

  .process-steps {
    grid-template-columns: repeat(2, 1fr);
    row-gap: 30px;
  }

  .process-step:nth-child(2)::after {
    display: none;
  }

  .estimate-inner {
    align-items: flex-start;
  }
}

/* MOBILE NAVIGATION AND LAYOUT */
@media (max-width: 720px) {
  :root {
    --gutter: 22px;
  }

  html {
    scroll-padding-top: 20px;
  }

  .header-inner {
    min-height: 0;
    flex-wrap: wrap;
    padding-block: 15px;
  }

  .brand img {
    max-width: 125px;
    max-height: 48px;
  }

  .main-nav {
    order: 3;
    width: 100%;
    justify-content: flex-start;
    gap: 20px;
    overflow-x: auto;
    padding: 12px 0 5px;
    scrollbar-width: thin;
  }

  .main-nav a:not(.btn) {
    flex-shrink: 0;
    font-size: .8rem;
  }

  .header-contact {
    margin-left: auto;
  }

  .header-phone {
    font-size: .78rem;
  }

  .header-contact .btn {
    min-height: 43px;
    padding: 10px 13px;
    font-size: .75rem;
  }

  .hero {
    min-height: 660px;
  }

  .hero::after {
    background: linear-gradient(
      90deg,
      rgba(25, 39, 36, .94),
      rgba(25, 39, 36, .68)
    );
  }

  .hero-content {
    width: 100%;
    padding-block: 85px;
  }

  .hero h1 {
    font-size: clamp(2.65rem, 11vw, 4rem);
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .trust-inner {
    grid-template-columns: 1fr;
  }

  .trust-item {
    padding: 22px 15px;
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, .18);
  }

  .trust-item:last-child {
    border-bottom: 0;
  }

  .intro-section,
  .services-section,
  .projects-section,
  .roof-section,
  .process-section,
  .contact-section {
    padding-block: 75px;
  }

  .intro-layout,
  .services-layout,
  .roof-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .intro-image-wrap {
    min-height: 0;
    margin-right: 12px;
  }

  .intro-image {
    height: 350px;
  }

  .services-intro {
