/* SMALL MOBILE */
@media (max-width: 420px) {
  :root {
    --gutter: 18px;
  }

  body {
    font-size: 15px;
  }

  .header-contact .btn {
    padding-inline: 10px;
    font-size: .69rem;
  }

  .header-phone {
    font-size: .7rem;
  }

  .brand img {
    max-width: 105px;
  }

  .hero {
    min-height: 610px;
  }

  .hero h1 {
    font-size: 2.55rem;
  }

  .service-item {
    grid-template-columns: 35px 1fr;
    gap: 12px;
  }

  .projects-gallery {
    grid-template-rows: 260px 220px 220px;
  }

  .project-caption {
    right: 18px;
    bottom: 18px;
    left: 18px;
  }
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }

  .project-item:hover img,
  .btn:hover {
    transform: none;
  }
}
